/** Confirmed grant only. The caller applies this atomically when +N appears. */
export function addFreeSpinGrant(remaining:number|null,total:number|null,played:number,added:number){
 if(!Number.isInteger(added)||added<=0)throw Error('Invalid free-spin grant');
 return {remaining:(remaining??0)+added,total:(total??played+(remaining??0))+added};
}
