/** One tap finishes only the presentation actions currently running. */
export class FlowControl {
 private actions=new Map<()=>void,((speed:number)=>void)|undefined>();
 private playbackSpeed=1;
 get speed(){return this.playbackSpeed;}
 track(finish:()=>void,onSpeed?:(speed:number)=>void){this.actions.set(finish,onSpeed);onSpeed?.(this.playbackSpeed);return()=>this.actions.delete(finish);}
 setSpeed(speed:number){
  if(!Number.isFinite(speed)||speed<=0)throw Error('Invalid presentation speed');
  if(speed===this.playbackSpeed)return;this.playbackSpeed=speed;
  for(const change of Array.from(this.actions.values()))change?.(speed);
 }
 advance(){for(const finish of Array.from(this.actions.keys()))finish();}
}
