import type {SpinResult,Win} from './SlotMain';
export const CAVE_SYMBOLS=['hammer','cauldron','a','k','q','dragon-wild','eggs','dragon-jackpot'] as const;
export const caveSymbol=(name:string)=>'golden-club-league-'+name;
export interface CaveTurn {board:string[];wins:Win[];extraSpins?:number;}
export interface CaveStage {board:string[];wins:Win[];scatters:number[];dragonCells:number[];remainingBefore:number;remainingConsumed:number;remainingAfter:number;added:number;}
export interface CavePlayback {triggerBoard:string[];triggerCells:number[];triggerWins:Win[];awarded:number;stages:CaveStage[];}
const scatters=(board:string[])=>board.flatMap((symbol,cell)=>symbol===caveSymbol('eggs')?[cell]:[]);
function boardOK(board:string[]){if(board.length!==9||board.some(symbol=>!CAVE_SYMBOLS.some(name=>caveSymbol(name)===symbol)))throw Error('Invalid cave board');}
function awards(input:Win[]){return input.map(win=>{if(!Number.isSafeInteger(win.amount)||win.amount<=0||!win.cells.length||new Set(win.cells).size!==win.cells.length||win.cells.some(cell=>!Number.isInteger(cell)||cell<0||cell>8))throw Error('Invalid cave award');return {...win,cells:[...win.cells]};});}
/** Crystal Cave's observed 3x3/10-line egg trigger. Natural ten-line table,
 * progressive dragon jackpot and probability distribution remain unverified. */
export function caveFreeSequence(triggerBoard:string[],triggerInput:Win[],awarded:number,turns:CaveTurn[],bet:number):SpinResult{
 boardOK(triggerBoard);const triggerCells=scatters(triggerBoard);
 if(triggerCells.length<3||!Number.isSafeInteger(bet)||bet<=0||!Number.isSafeInteger(awarded)||awarded<=0||awarded>1000)throw Error('Invalid cave trigger');
 let remaining=awarded;const triggerWins=awards(triggerInput),wins=[...triggerWins],stages:CaveStage[]=[];
 for(const turn of turns){
  if(remaining<=0)throw Error('Cave free spins ended');boardOK(turn.board);const remainingBefore=remaining;remaining--;
  const scatterCells=scatters(turn.board),added=turn.extraSpins??0;
  if(!Number.isSafeInteger(added)||added<0||remaining+added>1000||added&&scatterCells.length<3)throw Error('Invalid cave retrigger');
  const stageWins=awards(turn.wins),remainingConsumed=remaining;remaining+=added;wins.push(...stageWins);
  stages.push({board:[...turn.board],wins:stageWins,scatters:scatterCells,dragonCells:turn.board.flatMap((symbol,cell)=>symbol===caveSymbol('dragon-wild')?[cell]:[]),remainingBefore,remainingConsumed,remainingAfter:remaining,added});
 }
 if(remaining||!stages.length)throw Error('Incomplete cave free sequence');
 const payout=wins.reduce((sum,win)=>sum+win.amount,0);if(!Number.isSafeInteger(payout))throw Error('Cave payout overflow');
 return {bet,board:[...stages[stages.length-1].board],wins,payout,caveFeature:{triggerBoard:[...triggerBoard],triggerCells,triggerWins,awarded,stages}};
}
