import {vikingCollapse} from './VikingBoard';
type Refill=(column:number,row:number)=>number;
function checkBoard(board:readonly number[]){if(board.length!==49||board.some(s=>!Number.isInteger(s)||s<0||s>12))throw Error('Invalid Viking effect board');}
function checkCells(cells:readonly number[]){if(!cells.length||new Set(cells).size!==cells.length||cells.some(c=>!Number.isInteger(c)||c<0||c>=49))throw Error('Invalid Viking effect cells');}
function checkSymbol(symbol:number){if(!Number.isInteger(symbol)||symbol<0||symbol>8)throw Error('Effect target must be regular');}
function neighbours(a:number,b:number){return Math.max(Math.abs(a%7-b%7),Math.abs(Math.floor(a/7)-Math.floor(b/7)))===1;}
function finish(board:readonly number[],removed:number[],changes:{cell:number;to:number}[],refill:Refill){
 checkBoard(board);const before=[...board],transformed=[...board];
 const changed=changes.map(({cell,to})=>{checkSymbol(to);transformed[cell]=to;return {cell,from:before[cell],to};});
 const cleared=before.map((symbol,cell)=>removed.includes(cell)?-1:symbol);
 return {before,removed:[...removed],changed,cleared,transformed,...vikingCollapse(transformed,removed,refill)};
}
/** Executes an explicit four-slash plan. Exact source slash offsets and any
 * intersection priority are not established: intersecting plans are rejected,
 * not silently resolved using an invented original-game rule. */
export function vikingFenrir(board:readonly number[],lines:readonly {cells:readonly number[];action:'remove'|'transform'}[],target:number,refill:Refill){
 checkBoard(board);checkSymbol(target);
 if(lines.length!==4||lines.filter(l=>l.action==='remove').length!==2||lines.filter(l=>l.action==='transform').length!==2)throw Error('Fenrir requires two removal and two transformation slashes');
 for(const line of lines){
  checkCells(line.cells);if(line.cells.length<2)throw Error('Fenrir slash too short');
  const dx=line.cells[1]%7-line.cells[0]%7,dy=Math.floor(line.cells[1]/7)-Math.floor(line.cells[0]/7);
  if(Math.abs(dx)!==1||Math.abs(dy)!==1)throw Error('Fenrir slash must be diagonal');
  for(let i=1;i<line.cells.length;i++)if(line.cells[i]%7-line.cells[i-1]%7!==dx||Math.floor(line.cells[i]/7)-Math.floor(line.cells[i-1]/7)!==dy)throw Error('Broken Fenrir diagonal');
 }
 const all=lines.flatMap(l=>[...l.cells]);if(new Set(all).size!==all.length)throw Error('Fenrir intersection priority requires source verification');
 const removed=lines.filter(l=>l.action==='remove').flatMap(l=>[...l.cells]);
 const changes=lines.filter(l=>l.action==='transform').flatMap(l=>l.cells.map(cell=>({cell,to:target})));
 return {kind:'fenrir' as const,slashes:lines.map(l=>({action:l.action,cells:[...l.cells]})),...finish(board,removed,changes,refill)};
}
/** Path cells carry their explicit action so a snake may reveal its route in
 * order, before collapse. The planner owns path geometry/selection weights. */
export function vikingJormungandr(board:readonly number[],path:readonly number[],converted:readonly number[],target:number,refill:Refill){
 checkBoard(board);checkCells(path);checkCells(converted);checkSymbol(target);
 const edge=(c:number)=>c%7===0||c%7===6||c<7||c>=42;
 if(path.length<2||!edge(path[0])||!edge(path[path.length-1])||path.some((c,i)=>i>0&&!neighbours(path[i-1],c)))throw Error('Jormungandr needs an unbroken edge-to-edge path');
 if(converted.some(c=>!path.includes(c))||converted.length>=path.length)throw Error('Jormungandr path must contain removals and conversions');
 const removed=path.filter(c=>!converted.includes(c));
 return {kind:'jormungandr' as const,path:[...path],...finish(board,removed,converted.map(cell=>({cell,to:target})),refill)};
}
export interface VikingFireGroup {seed:number;burned:readonly number[];core:readonly number[];symbol:number;}
/** Provider visual CHARGE help: three different selected symbols are
 * duplicated while surrounding symbols are destroyed. Preserve each seed
 * and copy that selected type into its core before gravity/refill. Growth timing and distribution are
 * planner responsibilities; the executor never turns destruction into a win. */
export function vikingSurtr(board:readonly number[],groups:readonly VikingFireGroup[],refill:Refill){
 checkBoard(board);if(groups.length!==3)throw Error('Surtr requires three fire seeds');
 const all:number[]=[],selectedTypes=new Set<number>();
 for(const group of groups){
  checkCells(group.burned);checkCells(group.core);checkSymbol(group.symbol);
  if(group.symbol!==board[group.seed]||selectedTypes.has(group.symbol))throw Error('Surtr must duplicate three different selected symbols');
  selectedTypes.add(group.symbol);
  if(!group.core.includes(group.seed))throw Error('Surtr selected symbol must survive in its core');
  if(!group.burned.includes(group.seed)||group.core.some(c=>!group.burned.includes(c)))throw Error('Surtr core/seed outside burned region');
  const visited=new Set([group.seed]);let size=0;
  while(size!==visited.size){size=visited.size;for(const cell of group.burned)if([...visited].some(v=>neighbours(v,cell)))visited.add(cell);}
  if(visited.size!==group.burned.length)throw Error('Disconnected Surtr fire region');
  all.push(...group.burned);
 }
 if(new Set(all).size!==all.length)throw Error('Overlapping Surtr regions require explicit merged-core policy');
 const coreCells=groups.flatMap(g=>[...g.core]);
 const removed=all.filter(c=>!coreCells.includes(c));
 const result=finish(board,removed,groups.flatMap(g=>g.core.filter(cell=>cell!==g.seed).map(cell=>({cell,to:g.symbol}))),refill);
 return {kind:'surtr' as const,groups:groups.map(g=>({...g,burned:[...g.burned],core:[...g.core]})),burnedBoard:board.map((symbol,cell)=>all.includes(cell)&&!groups.some(g=>g.seed===cell)?-1:symbol),...result};
}
