/** Bonus entry costs: 400 coins = 14 tickets. Ticket balances use tenths. */
export const BONUS_COST_MULTIPLIER=20;
export function bonusTicketCost(baseBet:number):number {
 const tenths=baseBet*7;
 if(!Number.isSafeInteger(baseBet)||baseBet<=0||!Number.isSafeInteger(baseBet*BONUS_COST_MULTIPLIER)||!Number.isSafeInteger(tenths))throw Error('Invalid bonus bet');
 return tenths;
}
