const pixelFrames=new Map<string,SpriteFrame>();
// Bake tiny palette patterns once; spinning reels reuse these textures.
function drawPixels(g:Graphics,rows:string[],colors:Record<string,string>,x:number,y:number,unit:number,originY:number){
 const key=rows.join('/')+JSON.stringify(colors);let frame=pixelFrames.get(key);
 if(!frame){const width=12,height=rows.length,data=new Uint8Array(width*height*4);
  rows.forEach((row,ry)=>Array.from(row).forEach((c,rx)=>{if(!colors[c])return;const color=new Color(colors[c]),offset=(ry*width+rx)*4;data.set([color.r,color.g,color.b,255],offset);}));
  const image=new ImageAsset({_data:data,width,height,format:Texture2D.PixelFormat.RGBA8888,_compressed:false}),texture=new Texture2D();texture.image=image;texture.setFilters(Texture2D.Filter.NEAREST,Texture2D.Filter.NEAREST);frame=new SpriteFrame();frame.texture=texture;frame.addRef();pixelFrames.set(key,frame);
 }
 const node=new Node('pixel-sprite');node.layer=g.node.layer;g.node.addChild(node);const transform=node.addComponent(UITransform);transform.setContentSize(12*unit,rows.length*unit);node.setPosition(x,y+(originY+1-rows.length/2)*unit);const sprite=node.addComponent(Sprite);sprite.sizeMode=Sprite.SizeMode.CUSTOM;sprite.spriteFrame=frame;
}
