 const colors:Record<string,string>={h:'#382b35',s:skin==='black'?'#8e5b43':skin==='white'?'#f4d9c3':'#deb37a',k:'#182423',t:shirt,d:'#536372',w:'#fff0ce',a:'#ffdb77'};
