import type {SpinResult,Win} from './SlotMain';
import {RhinoBoard,rhinoEvaluate} from './RhinoRules';
import {RhinoRefill,rhinoTumble} from './RhinoTumble';

export const RHINO_MAX_WIN=20000;
export const rhinoSymbol=(symbol:number)=>'rhino-grand-ways-'+symbol;
export interface RhinoStage {
 board:RhinoBoard;
 multiplier:number;
 nextMultiplier:number;
 wins:Win[];
 rawPayout:number;
 payout:number;
 motion?:ReturnType<typeof rhinoTumble>;
 end?:'no-win'|'max-win';
}
export interface RhinoPlayback {
 stages:RhinoStage[];
 limit:number;
 termination:'no-win'|'max-win';
}
export function rhinoFlatBoard(board:RhinoBoard):string[]{
 const flat=Array<string>(48).fill('rhino-grand-ways-void');
 board.columns.forEach((column,col)=>column.forEach((symbol,row)=>{flat[col*7+row]=rhinoSymbol(symbol);}));
 board.top.forEach((symbol,index)=>{flat[42+index]=rhinoSymbol(symbol);});
 return flat;
}
const copyBoard=(board:RhinoBoard):RhinoBoard=>({columns:board.columns.map(column=>[...column]),top:[...board.top]});

/** Capped base-game result, also accepting the remaining whole-round budget.
 * Stops on the actual capped winning board; never fabricates a losing refill.
 * No natural reel distribution or free-spin multiplier timing is assumed here. */
export function rhinoRound(opening:RhinoBoard,bet:number,
 refill:(board:RhinoBoard,removed:number[],step:number)=>RhinoRefill,
 remainingBudget=bet*RHINO_MAX_WIN,bonusMultiplier?:number):SpinResult{
 const maximum=bet*RHINO_MAX_WIN;
 if(!Number.isSafeInteger(bet)||bet<=0||!Number.isSafeInteger(maximum))throw Error('Invalid Rhino settlement bet');
 if(!Number.isSafeInteger(remainingBudget)||remainingBudget<=0||remainingBudget>maximum)throw Error('Invalid Rhino settlement budget');
 if(bonusMultiplier!==undefined&&(!Number.isSafeInteger(bonusMultiplier)||bonusMultiplier<1))throw Error('Invalid Rhino bonus multiplier');
 let board=copyBoard(opening),paid=0,multiplier=bonusMultiplier??1;
 const stages:RhinoStage[]=[];
 for(let step=0;step<10000;step++){
  const evaluation=rhinoEvaluate(board,bet);
  const wins:Win[]=evaluation.wins.map(win=>{
   const multiplied=win.amount*multiplier;
   if(!Number.isSafeInteger(multiplied))throw Error('Rhino settlement requires whole-coin awards');
   const amount=Math.min(remainingBudget-paid,multiplied);paid+=amount;
   return {line:-1,symbol:rhinoSymbol(win.symbol),cells:[...win.cells],amount,multiplier};
  });
  const nextMultiplier=multiplier+(bonusMultiplier!==undefined&&evaluation.removedCells.length?1:0);
  const stage:RhinoStage={board,wins,multiplier,nextMultiplier,rawPayout:evaluation.payout*multiplier,payout:wins.reduce((sum,win)=>sum+win.amount,0)};
  stages.push(stage);
  if(paid===remainingBudget||!evaluation.removedCells.length){
   stage.end=paid===remainingBudget?'max-win':'no-win';
   return {bet,board:rhinoFlatBoard(board),wins:stages.flatMap(item=>item.wins),payout:paid,
    rhinoFeature:{stages,limit:remainingBudget,termination:stage.end},featureText:'가변 릴 · 연쇄'};
  }
  stage.motion=rhinoTumble(board,evaluation.removedCells,refill(copyBoard(board),[...evaluation.removedCells],step));
  board=stage.motion.after;
  multiplier=nextMultiplier;
 }
 throw Error('Rhino settlement chain did not converge');
}
