import {Color,Graphics,Rect,Size,Sprite,SpriteFrame,Texture2D,Node,UITransform} from 'cc';
import {voxelParts} from '../services/VoxelWardrobe';
const frames=new Map<string,SpriteFrame>();
const icons=new Map<string,SpriteFrame>();
const bounds:Record<string,number[]>={hair:[32,4,31,26],top:[25,35,46,37],pants:[33,70,31,21]};
let atlas:Texture2D|null=null;
/** Exactly five frames share one 480x128 texture, regardless of combinations. */
export function setVoxelAtlas(texture:Texture2D){
 if(atlas===texture)return;
 for(const frame of [...frames.values(),...icons.values()])frame.destroy();frames.clear();icons.clear();atlas=texture;
 voxelParts.forEach((part,i)=>{const frame=new SpriteFrame();frame.texture=texture;frame.rect=new Rect(i*96,0,96,128);frame.originalSize=new Size(96,128);frames.set(part,frame);
  const b=bounds[part];if(b){const icon=new SpriteFrame();icon.texture=texture;icon.rect=new Rect(i*96+b[0],b[1],b[2],b[3]);icon.originalSize=new Size(b[2],b[3]);icons.set(part,icon);}
 });
}
export function drawVoxelAvatar(g:Graphics,x:number,y:number,scale:number,colors:Record<string,string>,onlySlot?:string){
 if(frames.size!==voxelParts.length)return false;
 for(const part of voxelParts){
  if(onlySlot&&part!==onlySlot)continue;
  const node=new Node('voxel-'+part);node.layer=g.node.layer;g.node.addChild(node);
  const transform=node.addComponent(UITransform),b=onlySlot?bounds[part]:undefined;
  if(b){const ratio=scale*11/Math.max(b[2],b[3]);transform.setContentSize(b[2]*ratio,b[3]*ratio);}else transform.setContentSize(scale*16.5,scale*22);
  node.setPosition(x,y+(onlySlot?0:scale));
  const sprite=node.addComponent(Sprite);sprite.sizeMode=Sprite.SizeMode.CUSTOM;sprite.spriteFrame=(onlySlot?icons:frames).get(part)!;sprite.color=new Color(colors[part]||'#ffffff');
 }
 return true;
}
