 initialize(storage:Storage,languages:readonly string[]){this.storage=storage;this.device=deviceLocale(languages);let saved:string|null=null;try{saved=storage.getItem(LANGUAGE_STORAGE_KEY);}catch{/* Unavailable storage still permits device language. */}this.preference=saved&&LOCALES.includes(saved as Locale)?saved as Locale:'device';}
