  for(const template of this.templates){if(['\n',' · ','  /  '].some(separator=>source.includes(separator)&&!template.key.includes(separator)))continue;const match=template.pattern.exec(source);if(match){const values:Record<string,string>={};template.names.forEach((name,index)=>values[name]=this.text(match[index+1],depth+1));return this.t(template.key,values);}}
