/** Board mechanics shared by Viking's paid removals and destruction effects.
 * Values0..8 are regular;9..12 are god WILDs. No award is inferred here. */
export interface VikingFall {from:number;to:number;symbol:number;}
export interface VikingSpawn {cell:number;symbol:number;}
export function vikingCollapse(board:readonly number[],removed:readonly number[],pick:(column:number,row:number)=>number){
 if(board.length!==49||board.some(s=>!Number.isInteger(s)||s<0||s>12))throw Error('Invalid Viking board');
 const erased=new Set(removed);
 if(erased.size!==removed.length||removed.some(c=>!Number.isInteger(c)||c<0||c>=49))throw Error('Invalid Viking removal');
 const after=Array<number>(49),falls:VikingFall[]=[],spawned:VikingSpawn[]=[];
 for(let column=0;column<7;column++){
  const survivors=Array.from({length:7},(_,row)=>row*7+column).filter(cell=>!erased.has(cell));
  const empty=7-survivors.length;
  survivors.forEach((from,index)=>{
   const to=(empty+index)*7+column;after[to]=board[from];
   if(from!==to)falls.push({from,to,symbol:board[from]});
  });
  for(let row=0;row<empty;row++){
   const symbol=pick(column,row),cell=row*7+column;
   if(!Number.isInteger(symbol)||symbol<0||symbol>8)throw Error('Invalid Viking ordinary refill');
   after[cell]=symbol;spawned.push({cell,symbol});
  }
 }
 return{after,falls,spawned};
}
