import type {Win} from './SlotMain';
import {ROAD_ART,roadSymbol as s} from './RoadFeature';

/** Total-bet pays transcribed from the official 1.3.11 demo at a €1 bet.
 * This evaluator covers unit-size, unboosted symbols only. Vehicle multiplier
 * combination and expanded-symbol ownership require separate verified rules. */
export const ROAD_PAYS:number[][]=[
 [.15,.25,.5],[.15,.25,.75],[.2,.3,1],[.2,.3,1.25],[.25,.35,1.5],
 [.3,.4,2],[.3,.4,2.5],[.35,.5,3],[.35,.6,3.75],[.4,.75,5],
];
const regular=ROAD_ART.slice(0,10).map(s),wilds=ROAD_ART.slice(10,14).map(s);
/** Enumerate physical connected paths, not unrestricted all-ways products. */
export function roadConnectedPaths(rows:number,length=5):number[][]{
 if(![3,4,5].includes(rows)||!Number.isInteger(length)||length<1||length>5)throw Error('Invalid connected Road geometry');
 let paths=Array.from({length:rows},(_,row)=>[row*5]);
 for(let col=1;col<length;col++)paths=paths.flatMap(path=>{
  const row=Math.floor(path[path.length-1]/5);
  return [-1,0,1].map(offset=>row+offset).filter(next=>next>=0&&next<rows).map(next=>[...path,next*5+col]);
 });
 return paths;
}
export function roadUnboostedWins(board:readonly string[],rows:number,bet:number):Win[]{
 if(board.length!==rows*5||!Number.isSafeInteger(bet)||bet<1||board.some(id=>!ROAD_ART.some(art=>s(art)===id)))throw Error('Invalid Road pay board');
 roadConnectedPaths(rows,1);
 if(board.every(id=>wilds.includes(id)))return[{line:-1,symbol:s('collision_wild'),amount:bet*36000,cells:board.map((_,cell)=>cell)}];
 const best=new Map<string,{symbol:string;pay:number;cells:number[]}>();
 for(let index=0;index<regular.length;index++){
  const matches=(cell:number)=>board[cell]===regular[index]||wilds.includes(board[cell]);
  const visit=(path:number[])=>{
   const col=path.length,row=Math.floor(path[col-1]/5);
   const next=col===5?[]:[-1,0,1].map(offset=>row+offset).filter(r=>r>=0&&r<rows).map(r=>r*5+col).filter(matches);
   if(next.length){next.forEach(cell=>visit([...path,cell]));return;}
   if(col<3)return;
   const key=path.join(','),pay=ROAD_PAYS[index][col-3],previous=best.get(key);
   if(!previous||pay>previous.pay)best.set(key,{symbol:regular[index],pay,cells:path});
  };
  for(let row=0;row<rows;row++)if(matches(row*5))visit([row*5]);
 }
 // A shorter all-wild prefix is not an extra award when a longer winning
 // combination already owns that physical path. Different branches still pay.
 const entries=[...best.values()].filter(item=>!item.cells.every(cell=>wilds.includes(board[cell]))||![...best.values()].some(other=>other.cells.length>item.cells.length&&item.cells.every((cell,i)=>other.cells[i]===cell)));
 const groups=new Map<string,{symbol:string;raw:number;cells:Set<number>}>();
 for(const item of entries){
  const key=item.symbol+':'+item.cells.length,group=groups.get(key)||{symbol:item.symbol,raw:0,cells:new Set<number>()};
  group.raw+=item.pay*bet;item.cells.forEach(cell=>group.cells.add(cell));groups.set(key,group);
 }
 // Round once per symbol/length group so small bets do not lose each tiny way.
 return [...groups.values()].map(group=>({line:-1,symbol:group.symbol,amount:Math.round(group.raw),cells:[...group.cells].sort((a,b)=>a-b)})).filter(win=>win.amount>0);
}
