/** Per-game plans combine the researched rule profile with an actual UI/sound playback contract. */
export const socialPresentationFor=(spec:SocialSlotSpec,profile:SocialFeatureProfile):SlotPresentation=>{
 const base=spec.id==='moon-princessa'?fp('수호자 게이지 · 전체 제거 대기','달빛 보너스 확정','직선 매치 · 달빛 배수 상승','수호자 힘 변환·WILD·제거, 세 힘의TRINITY, 전체 제거 뒤4/5/8회 선택','featureLand',.3,.22):featurePresentation[profile.feature];
 return{...base,evidence:profile.referenceStatus==='verified-game'?'official-rules':'source-title-pending',bonusInText:`${spec.subtitle} · ${base.triggerText}`,totalWinText:`${spec.subtitle} · TOTAL WIN`,signature:profile.rules[profile.rules.length-1]};
};
export const socialPresentationProfiles:Record<string,SlotPresentation>=Object.fromEntries(socialSlotCatalog.map(spec=>[spec.id,socialPresentationFor(spec,socialFeatureProfiles[spec.id])]));
