/** FIFO display lifetime; new awards never restart the active card's clock. */
export class PerkToastQueue<T> {
 readonly lifetime=3;
 private pending:T[]=[];
 current:T|undefined;
 elapsed=0;
 add(entry:T){this.pending.push(entry);if(this.current===undefined)this.next();}
 update(seconds:number){
  if(this.current===undefined||!Number.isFinite(seconds)||seconds<=0)return;
  this.elapsed+=seconds;
  // A newly displayed card receives its own full lifetime, even after a slow frame.
  if(this.elapsed>=this.lifetime)this.next();
 }
 clear(){this.pending=[];this.current=undefined;this.elapsed=0;}
 private next(){this.current=this.pending.shift();this.elapsed=0;}
}
