import {legacyRound,legacyAddSelection} from './LegacyFeature';
import {legacyResult} from './LegacyResult';
import type {SpinResult} from './SlotMain';

/** Original sampling weights for our version, not the provider's private strips.
 * Provisional math: distribution and purchase normalization must be audited. */
export const LEGACY_WEIGHTS=[4,5,7,7,14,14,17,17,17] as const;
export const LEGACY_ALTAR_CHANCE=.103;
export function legacySampler(rng:()=>number,altarChance=LEGACY_ALTAR_CHANCE){
 if(!Number.isFinite(altarChance)||altarChance<0||altarChance>1)throw Error('Invalid Legacy altar chance');
 const roll=()=>{const n=rng();if(!Number.isFinite(n)||n<0||n>=1)throw Error('Invalid Legacy RNG');return n;};
 const pick=()=>{let n=roll()*LEGACY_WEIGHTS.reduce((a,b)=>a+b,0);for(let i=0;i<9;i++){n-=LEGACY_WEIGHTS[i];if(n<0)return i;}return 8;};
 return{roll,board:()=>{const board=Array.from({length:15},pick);for(let col=0;col<5;col++)if(roll()<altarChance)board[Math.floor(roll()*3)*5+col]=9;return board;}};
}
export interface LegacyGameOptions {
 /** Deterministic fixture source for tests/isolated playback. */
 board?:(round:number)=>number[];
 /** Offline sampler calibration only; live calls use the exported fixed value. */
 altarChance?:number;
}
export function legacyGame(bet:number,rng:()=>number=Math.random,options:LegacyGameOptions={}):SpinResult{
 const sample=legacySampler(rng,options.altarChance),board=(index:number)=>options.board?options.board(index):sample.board(),id='legacy-of-wildead',maximum=bet*5000;
 const base=legacyRound(board(0),bet,[],maximum),first=legacyResult(id,bet,base);
 if(!base.freeSpinsAdded||base.payout>=maximum)return first;
 let selected=legacyAddSelection([],sample.roll),left=8,total=base.payout,played=0;
 const initial=selected[0],rounds=[first];
 while(left>0&&total<maximum){
  left--;played++;
  const calculated=legacyRound(board(played),bet,selected,maximum-total),round=legacyResult(id,bet,calculated);
  total+=round.payout;
  const added=total<maximum?calculated.freeSpinsAdded:0;
  if(added){selected=legacyAddSelection(selected,sample.roll);left+=added;}
  if(total>=maximum)left=0;
  round.freeSpinsAdded=added;round.freeSpinsRemaining=left;
  round.roundLabel='프리스핀 '+played+' · 남은 '+left;
  round.legacyFeature!.selectedAfter=selected.map(symbol=>id+'-'+symbol);
  rounds.push(round);
 }
 return{bet,board:[...rounds[rounds.length-1].board],rounds,wins:rounds.flatMap(r=>r.wins),payout:total,freeSpinsAwarded:8,selectedSymbol:id+'-'+initial,featureName:'모래의 기억 · 확장 심볼'};
}
