import type {Cascade,SpinResult,Win} from './SlotMain';
/** Original BET £1 paytable, 3/4/5/6 consecutive reels. */
export const FIRE_PAYS=[[.75,2,4,7.5],[.5,.75,2,3.75],[.45,.6,1.5,2.5],[.4,.55,1.25,2],[.35,.5,1,1.75],[.3,.4,.8,1.5],[.25,.35,.7,1.25],[.2,.3,.6,1.1],[.2,.3,.6,1.05],[.2,.3,.6,1]];
export interface MineStage {rows:number;nextRows:number;beforeMultiplier:number;afterMultiplier:number;bombs:number[];mining:{cells:number[];wilds:number[]}[];blast:number[];}
export interface MineFeature {stages:MineStage[];}
export interface MineOptions {id:string;bet:number;pick:(column:number)=>string;limit?:number;opening?:string[];}
const flat=(columns:string[][],id:string)=>Array.from({length:36},(_,i)=>columns[i%6][Math.floor(i/6)]??id+'-rock');
export function mineRound(o:MineOptions):SpinResult{
 const {id,bet}=o,wild=id+'-wild',scatter=id+'-scatter';let rows=3,multiplier=1,left=o.limit??bet*60000;
 let columns=Array.from({length:6},(_,col)=>Array.from({length:3},(_,row)=>o.opening?.[row*6+col]??o.pick(col)));
 const cascades:Cascade[]=[],stages:MineStage[]=[],wins:Win[]=[];
 for(let iteration=0;iteration<1024;iteration++){
  const board=flat(columns,id),stageWins:Win[]=[];
  for(let symbol=0;symbol<10;symbol++){
   const cells:number[]=[],counts:number[]=[];let natural=false;
   for(let col=0;col<6;col++){
    const hits=columns[col].flatMap((s,row)=>s===id+'-'+symbol||s===wild?[row*6+col]:[]);
    if(!hits.length)break;natural=natural||hits.some(cell=>board[cell]!==wild);cells.push(...hits);counts.push(hits.length);
   }
   if(counts.length<3||!natural&&symbol!==0)continue;
   const amount=Math.min(left,Math.round(bet*FIRE_PAYS[symbol][counts.length-3]*counts.reduce((a,b)=>a*b,1)*multiplier));
   if(amount){left-=amount;stageWins.push({line:-1,symbol:id+'-'+symbol,cells,amount,multiplier});}
  }
  const removed=new Set(stageWins.flatMap(w=>w.cells)),mining:MineStage['mining']=[],bombs:number[]=[];
  if(!stageWins.length)for(let row=0;row<rows;row++)for(let col=0;col<6;){
   const symbol=board[row*6+col];let end=col+1;while(end<6&&board[row*6+end]===symbol)end++;
   if(/^\d+$/.test(symbol.slice(id.length+1))&&end-col>=3){
    const cells=Array.from({length:end-col},(_,i)=>row*6+col+i),wilds=cells.slice(1,-1);mining.push({cells,wilds});cells.forEach(c=>removed.add(c));
    for(let r=0;r<row;r++)for(let c=0;c<6;c++){const at=r*6+c;if(board[at]!==wild&&board[at]!==scatter)removed.add(at);}
   }col=end;
  }
  if(!mining.length)board.forEach((s,cell)=>{if(s!==wild)return;bombs.push(cell);removed.add(cell);const row=Math.floor(cell/6),col=cell%6;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){const r=row+dy,c=col+dx,at=r*6+c;if(r>=0&&r<rows&&c>=0&&c<6&&board[at]!==scatter)removed.add(at);}});
  const nextMultiplier=multiplier+bombs.length,nextRows=removed.size?Math.min(6,rows+1):rows;
  const stage:Cascade={board,wins:stageWins,payout:stageWins.reduce((n,w)=>n+w.amount,0),multiplier,cellMultipliers:Array(36).fill(0),nextMultipliers:Array(36).fill(0),drops:[],removedCells:[...removed]};
  cascades.push(stage);stages.push({rows,nextRows,beforeMultiplier:multiplier,afterMultiplier:nextMultiplier,bombs,mining,blast:[...removed]});wins.push(...stageWins);
  if(!removed.size||left<=0)return{bet,board,wins,payout:wins.reduce((n,w)=>n+w.amount,0),cascades,mineFeature:{stages}};
  const created=new Set(mining.flatMap(m=>m.wilds));
  columns=columns.map((column,col)=>{
   const kept=column.map((s,row)=>({symbol:created.has(row*6+col)?wild:s,from:row*6+col})).filter(s=>!removed.has(s.from)||created.has(s.from));
   const incoming=nextRows-kept.length;return Array.from({length:nextRows},(_,row)=>{const old=row<incoming?undefined:kept[row-incoming],symbol=old?.symbol??o.pick(col),to=row*6+col;stage.drops.push({symbol,from:old?.from??(row-incoming)*6+col,to});return symbol;});
  });for(let row=nextRows;row<6;row++)for(let col=0;col<6;col++)stage.drops.push({from:row*6+col,to:row*6+col,symbol:id+'-rock'});rows=nextRows;multiplier=nextMultiplier;
 }
 throw Error('Mine cascade did not converge');
}

export type WagonKind='coin'|'multiply'|'dynamite'|'bag'|'chest'|'miner';
export interface WagonEnhancer {kind:WagonKind;value:number;}
export interface WagonCoin {cell:number;value:number;kind:'coin'|'bag'|'chest'|'miner';}
export interface WagonEvent {kind:'land'|'multiply'|'blast'|'collect'|'chest-tick'|'miner-reset';cell:number;from:number[];value:number;coins:WagonCoin[];open:number[];chests:number[];}
export interface WagonFeature {before:WagonCoin[];after:WagonCoin[];openBefore:number[];openAfter:number[];enhancers:WagonEnhancer[];events:WagonEvent[];chestsBefore:number[];chests:number[];remaining:number;final:boolean;}
export interface WagonOptions {id:string;bet:number;trigger:number;limit:number;rng:()=>number;enhancer:()=>WagonEnhancer;landChance?:number;}
/** Holds coin positions between spins. Money is awarded exactly once at feature exit. */
export function wagonSequence(o:WagonOptions):SpinResult[]{
 const {id,bet}=o,initialRows=Math.min(4,Math.max(2,o.trigger-1)),open=new Set(Array.from({length:initialRows*6},(_,i)=>i)),chests=Array(6).fill(0),coins=new Map<number,WagonCoin>(),rounds:SpinResult[]=[];
 let remaining=3;
 const snapshot=()=>[...coins.values()].map(c=>({...c})),board=()=>Array.from({length:36},(_,i)=>i>=24?id+'-void':coins.has(i)?id+'-'+coins.get(i)!.kind:open.has(i)?id+'-void':id+'-rock');
 for(let spin=0;spin<1024;spin++){
  const before=snapshot(),openBefore=[...open],chestsBefore=[...chests],enhancers=Array.from({length:6},o.enhancer),events:WagonEvent[]=[];remaining--;
  const event=(kind:WagonEvent['kind'],cell:number,from:number[],value:number)=>events.push({kind,cell,from,value,coins:snapshot(),open:[...open],chests:[...chests]});
  const targets=[...open].filter(cell=>!coins.has(cell)&&o.rng()<(o.landChance??.07));if(targets.length)remaining=3;
  for(const cell of targets){
   const col=cell%6,e=enhancers[col];coins.set(cell,{cell,value:e.kind==='coin'?e.value:1,kind:'coin'});event('land',cell,[],coins.get(cell)!.value);
   if(e.kind==='multiply'){const from=[...coins.keys()].filter(c=>c%6===col);for(const c of from)coins.get(c)!.value=Math.min(o.limit/bet,coins.get(c)!.value*e.value);event('multiply',cell,from,e.value);}
   if(e.kind==='dynamite'){
    coins.get(cell)!.value=e.value;const destroyed:number[]=[];
    for(let n=0;n<e.value;n++){const blocked=Array.from({length:4},(_,r)=>r*6+col).find(c=>!open.has(c));if(blocked!==undefined){open.add(blocked);destroyed.push(blocked);}else if(!chests[col])chests[col]=1;else for(const c of coins.values())if(c.cell%6===col)c.value++;}
    event('blast',cell,destroyed,e.value);
   }
   if(e.kind==='bag'||e.kind==='chest'||e.kind==='miner'){
    const existingMiner=[...coins.values()].find(c=>c.kind==='miner');
    if(e.kind==='miner'&&existingMiner){coins.get(cell)!.value=1;existingMiner.value=[...coins.values()].reduce((n,c)=>n+c.value,0);event('miner-reset',existingMiner.cell,[cell],existingMiner.value);}
    else{const from=[...coins.keys()].filter(c=>e.kind!=='bag'||c%6===col),sum=from.reduce((n,c)=>n+coins.get(c)!.value,0);if(e.kind!=='miner')for(const c of from)if(c!==cell&&coins.get(c)!.kind!=='miner')coins.delete(c);coins.set(cell,{cell,value:sum,kind:e.kind});event('collect',cell,from,sum);}
   }
  }
  for(const miner of [...coins.values()].filter(c=>c.kind==='miner'&&before.some(old=>old.cell===c.cell&&old.kind==='miner'))){const from=[...coins.keys()].filter(c=>c!==miner.cell);miner.value+=from.reduce((n,c)=>n+coins.get(c)!.value,0);event('collect',miner.cell,from,miner.value);}
  for(let col=0;col<6;col++)if(chests[col]){const from=[...coins.keys()].filter(c=>c%6===col),sum=from.reduce((n,c)=>n+coins.get(c)!.value,0);chests[col]+=sum;event('chest-tick',24+col,from,sum);}
  const sum=()=>[...coins.values()].reduce((n,c)=>n+c.value,0)+chests.reduce((n,c)=>n+Math.max(0,c-1),0),final=remaining===0||coins.size===24||sum()*bet>=o.limit;
  if(final)for(let tick=0;tick<3;tick++)for(let col=0;col<6;col++)if(chests[col]){const from=[...coins.keys()].filter(c=>c%6===col),value=from.reduce((n,c)=>n+coins.get(c)!.value,0);chests[col]+=value;event('chest-tick',24+col,from,value);}
  const payout=final?Math.min(o.limit,Math.round(sum()*bet)):0,wins:Win[]=payout?[{line:-1,symbol:id+'-coin',cells:[...coins.keys()],amount:payout}]:[];
  rounds.push({bet,board:board(),wins,payout,symbolValues:Array.from({length:36},(_,i)=>coins.get(i)?.value||0),heldAtStart:before.map(c=>({cell:c.cell,symbol:id+'-'+c.kind,value:c.value})),roundLabel:'WAGON SPINS · 남은 '+remaining+'회',freeSpinsRemaining:remaining,wagonFeature:{before,after:snapshot(),openBefore,openAfter:[...open],enhancers,events,chestsBefore,chests:[...chests],remaining,final}});
  if(final)return rounds;
 }
 throw Error('Wagon feature did not converge');
}
